-- 2. Type conversions (guarded per column)

-- actionable_registries
DO $$
BEGIN
    IF to_regclass('public.actionable_registries') IS NOT NULL THEN
    IF EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = 'public' AND table_name = 'actionable_registries'
          AND column_name = 'id' AND data_type = 'character varying'
    ) THEN
        ALTER TABLE actionable_registries ALTER COLUMN id TYPE uuid USING NULLIF(id, '')::uuid;
    END IF;
    IF EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = 'public' AND table_name = 'actionable_registries'
          AND column_name = 'organization_id' AND data_type = 'character varying'
    ) THEN
        ALTER TABLE actionable_registries ALTER COLUMN organization_id TYPE uuid USING NULLIF(organization_id, '')::uuid;
    END IF;
    IF EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = 'public' AND table_name = 'actionable_registries'
          AND column_name = 'assigned_owner_id' AND data_type = 'character varying'
    ) THEN
        ALTER TABLE actionable_registries ALTER COLUMN assigned_owner_id TYPE uuid USING NULLIF(assigned_owner_id, '')::uuid;
    END IF;
    IF EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = 'public' AND table_name = 'actionable_registries'
          AND column_name = 'assigned_team_id' AND data_type = 'character varying'
    ) THEN
        ALTER TABLE actionable_registries ALTER COLUMN assigned_team_id TYPE uuid USING NULLIF(assigned_team_id, '')::uuid;
    END IF;
    IF EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = 'public' AND table_name = 'actionable_registries'
          AND column_name = 'created_by' AND data_type = 'character varying'
    ) THEN
        ALTER TABLE actionable_registries ALTER COLUMN created_by TYPE uuid USING NULLIF(created_by, '')::uuid;
    END IF;
    END IF;
END $$;

