-- 3. Re-add FKs with explicit names

DO $$
BEGIN
    IF to_regclass('public.actionable_registries') IS NOT NULL
       AND to_regclass('public.users') IS NOT NULL
       AND NOT EXISTS (
        SELECT 1 FROM pg_constraint con
        JOIN pg_class src ON src.oid = con.conrelid
        JOIN unnest(con.conkey) AS k(attnum) ON TRUE
        JOIN pg_attribute a ON a.attrelid = src.oid AND a.attnum = k.attnum
        WHERE con.contype = 'f' AND src.relname = 'actionable_registries' AND a.attname = 'assigned_owner_id'
    ) THEN
        ALTER TABLE actionable_registries ADD CONSTRAINT fk_actionable_registries_assigned_owner_id
            FOREIGN KEY (assigned_owner_id) REFERENCES users (id);
    END IF;
END $$;

