       AND to_regclass('public.task_boards') IS NOT NULL
       AND NOT EXISTS (
        SELECT 1 FROM pg_constraint con
        JOIN pg_class src ON src.oid = con.conrelid
        JOIN unnest(con.conkey) AS k(attnum) ON TRUE
