        WHERE con.contype = 'f' AND src.relname = 'task_rules' AND a.attname = 'target_board_id'
    ) THEN
        ALTER TABLE task_rules ADD CONSTRAINT fk_task_rules_target_board_id
            FOREIGN KEY (target_board_id) REFERENCES task_boards (id);
    END IF;
END $$;

